document.getElementById('pullBtn').onclick=()=>{if(!state.tickets)return;state.tickets--;let results=[];for(let i=0;i<10;i++){let r=Math.random(),rarity=r<.05?'epic':r<.30?'rare':'common';let pool=avatarPool.filter((_,idx)=>rarity==='epic'?idx>=15:rarity==='rare'?idx>=10&&idx<15:idx<10);let av=pool[Math.floor(Math.random()*pool.length)];results.push({name:av[0],icon:av[1],rarity});state.avatars.push(av[0])}syncUI();const grid=document.getElementById('avatarGrid');grid.innerHTML='';results.forEach((a,i)=>{const el=document.createElement('div');el.className='avatar-item '+a.rarity;el.style.animationDelay=(i*.055)+'s';el.innerHTML=`<div class="face">${a.icon}</div><div class="av-name">${a.name}</div><div class="rarity">${a.rarity==='epic'?'✦ ÉPICO':a.rarity==='rare'?'◆ RARO':'COMUM'}</div>`;grid.append(el)});toast('Dez avatares revelados!')};
function rng(n){const v=Math.sin(n*127.1+311.7)*43758.5453;return v-Math.floor(v)}
function project(x,y,z){const u=Math.min(W/27,H/21,27);return{x:W*.5+(x-player.x-z+player.z)*u*.87,y:H*.49+((x-player.x)+(z-player.z))*u*.36-y*u*1.22,u}}
function poly(points,fill,stroke=null,width=1){ctx.beginPath();points.forEach((p,i)=>{const q=project(p[0],p[1]||0,p[2]);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function ground(){const u=Math.min(W/27,H/21,27),radius=Math.ceil(Math.max(W,H)/u/1.4)+2;const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#1c3433');bg.addColorStop(.55,'#263f37');bg.addColorStop(1,'#324638');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);let tiles=[];for(let x=Math.floor(player.x-radius);x<player.x+radius;x++)for(let z=Math.floor(player.z-radius);z<player.z+radius;z++)tiles.push({x,z,d:x+z});tiles.sort((a,b)=>a.d-b.d);for(const t of tiles){let r=rng(t.x*97+t.z*53),cx=t.x,cz=t.z;let a=project(cx,0,cz),b=project(cx+1,0,cz),c=project(cx+1,0,cz+1),d=project(cx,0,cz+1);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fillStyle=r>.82?'#395640':r>.28?'#304d3e':'#2d493c';ctx.fill();if(r>.988){ctx.fillStyle='#77905a';ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(a.x+(b.x-a.x)*.5,a.y+2,1.3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
// old footpath crossing the clearing
ctx.save();ctx.globalAlpha=.3;ctx.strokeStyle='#c9b982';ctx.lineWidth=u*.47;ctx.lineCap='round';ctx.beginPath();let p=project(-13,0,8),q=project(12,0,-6);ctx.moveTo(p.x,p.y);ctx.quadraticCurveTo(W*.57,H*.62,q.x,q.y);ctx.stroke();ctx.restore();
}
function drawTree(x,z,seed){const p=project(x,0,z),u=p.u,s=.74+rng(seed)*.55;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='#12292388';ctx.beginPath();ctx.ellipse(0,2,u*.6,u*.25,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#584838';ctx.fillRect(-u*.09,-u*.96,u*.18,u*.97);ctx.fillStyle='#1b392f';ctx.beginPath();ctx.moveTo(0,-u*3.1);ctx.lineTo(-u*.85,-u*1.1);ctx.quadraticCurveTo(-u*.9,-u*.7,0,-u*.8);ctx.quadraticCurveTo(u*.95,-u*.65,u*.83,-u*1.15);ctx.closePath();ctx.fill();ctx.fillStyle='#294c3a';ctx.beginPath();ctx.moveTo(-u*.05,-u*3.35);ctx.lineTo(-u*.61,-u*1.65);ctx.quadraticCurveTo(-u*.8,-u*1.2,-u*.04,-u*1.4);ctx.quadraticCurveTo(u*.8,-u*1.1,u*.57,-u*1.69);ctx.closePath();ctx.fill();ctx.fillStyle='#476447';ctx.beginPath();ctx.ellipse(-u*.18,-u*2.35,u*.19,u*.55,.5,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawCrystal(x,z){const p=project(x,0,z),u=p.u;ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#10231e88';ctx.beginPath();ctx.ellipse(0,0,u*.5,u*.18,0,0,Math.PI*2);ctx.fill();ctx.shadowColor='#88e3d0';ctx.shadowBlur=u*.45;ctx.fillStyle='#60bdb0';ctx.beginPath();ctx.moveTo(0,-u*1.2);ctx.lineTo(u*.24,-u*.35);ctx.lineTo(u*.12,0);ctx.lineTo(-u*.2,0);ctx.lineTo(-u*.28,-u*.42);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#c7ffdf';ctx.beginPath();ctx.moveTo(0,-u*1.2);ctx.lineTo(u*.03,-u*.38);ctx.lineTo(-u*.1,-u*.2);ctx.lineTo(-u*.16,-u*.48);ctx.closePath();ctx.fill();ctx.restore()}
function drawFlower(x,z,n){const p=project(x,0,z),u=p.u;ctx.strokeStyle='#9bb77c';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,p.y-u*.35);ctx.stroke();ctx.fillStyle=n%2?'#e7c779':'#e9dfbc';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(p.x+Math.cos(i*1.256)*2,p.y-u*.38+Math.sin(i*1.256)*2,2,0,Math.PI*2);ctx.fill()}}
function drawSlime(e){const p=project(e.x,0,e.z),u=p.u,hop=Math.sin(time*5+e.phase)*u*.055;ctx.save();ctx.translate(p.x,p.y-hop);ctx.fillStyle='#13231f77';ctx.beginPath();ctx.ellipse(0,1,u*.47,u*.19,0,0,Math.PI*2);ctx.fill();const col=e.flash?'#fff0c1':'#9bc873';ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(-u*.42,-u*.12);ctx.quadraticCurveTo(-u*.38,-u*.78,0,-u*.75);ctx.quadraticCurveTo(u*.4,-u*.7,u*.43,-u*.12);ctx.quadraticCurveTo(0,u*.03,-u*.42,-u*.12);ctx.fill();ctx.fillStyle='#d5ef9e';ctx.globalAlpha=.65;ctx.beginPath();ctx.ellipse(-u*.12,-u*.51,u*.12,u*.065,-.3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#263a30';ctx.beginPath();ctx.arc(-u*.14,-u*.34,u*.035,0,Math.PI*2);ctx.arc(u*.14,-u*.34,u*.035,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#435938';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-u*.27,u*.07,.2,Math.PI-.2);ctx.stroke();if(e.hp<e.maxHp){ctx.fillStyle='#14221e';ctx.fillRect(-u*.34,-u*.94,u*.68,3);ctx.fillStyle='#d97c61';ctx.fillRect(-u*.34,-u*.94,u*.68*(e.hp/e.maxHp),3)}if(e.target){ctx.strokeStyle='#f0da8a';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,u*.6,u*.23,0,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function drawHero(){const p=project(player.x,0,player.z),u=p.u,c=getClass();ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#10211d88';ctx.beginPath();ctx.ellipse(0,1,u*.38,u*.17,0,0,Math.PI*2);ctx.fill();let bob=Math.sin(time*6)*u*.025;ctx.translate(0,-bob);if(player.invuln>0&&Math.floor(time*15)%2)ctx.globalAlpha=.6;
// cape, robes and shoulders
ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(-u*.19,-u*.89);ctx.quadraticCurveTo(-u*.34,-u*.5,-u*.29,-u*.16);ctx.lineTo(0,-u*.27);ctx.lineTo(u*.28,-u*.15);ctx.quadraticCurveTo(u*.37,-u*.57,u*.18,-u*.9);ctx.closePath();ctx.fill();ctx.fillStyle='#263c36';ctx.beginPath();ctx.moveTo(-u*.18,-u*.87);ctx.lineTo(u*.18,-u*.87);ctx.lineTo(u*.24,-u*.17);ctx.lineTo(-u*.23,-u*.17);ctx.closePath();ctx.fill();ctx.fillStyle='#cfb977';ctx.fillRect(-u*.21,-u*.56,u*.42,u*.045);ctx.fillStyle='#dfc9a0';ctx.beginPath();ctx.arc(0,-u*1.04,u*.18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#563e34';ctx.beginPath();ctx.arc(0,-u*1.1,u*.18,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#27332e';ctx.fillRect(-u*.12,-u*.83,u*.24,u*.08);
// staff and glowing crystal
ctx.strokeStyle='#96764c';ctx.lineWidth=u*.075;ctx.beginPath();ctx.moveTo(u*.26,-u*.2);ctx.lineTo(u*.37,-u*1.23);ctx.stroke();ctx.shadowColor=c.color;ctx.shadowBlur=u*.38;ctx.fillStyle=c.color;ctx.beginPath();ctx.arc(u*.38,-u*1.27,u*.12,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f2e7c5';ctx.beginPath();ctx.arc(u*.38,-u*1.27,u*.045,0,Math.PI*2);ctx.fill();if(player.attackCd>.3){ctx.strokeStyle='#f1d88a';ctx.lineWidth=3;ctx.beginPath();ctx.arc(u*.38,-u*.48,u*.45,-1.1,.65);ctx.stroke()}if(player.skillCd>1.3){ctx.strokeStyle=c.color;ctx.lineWidth=2;ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(0,-u*.62,u*.55,time*3,time*3+4);ctx.stroke()}ctx.restore()}

