const scenery=[];for(let x=-32;x<=32;x+=2)for(let z=-32;z<=32;z+=2){if(rng(x*43+z*13)>.77&&Math.hypot(x,z)>5)scenery.push({x:x+(rng(x+z*4)-.5),z:z+(rng(z-x*7)-.5),type:rng(x*11+z*5)>.84?'crystal':'tree',seed:x*43+z*13})}for(let i=0;i<42;i++){let x=(rng(i*31)-.5)*35,z=(rng(i*79)-.5)*35;if(Math.hypot(x,z)>3)scenery.push({x,z,type:'flower',seed:i})}
function spawnEnemy(){let a=Math.random()*Math.PI*2,r=4+Math.random()*8;return{x:player.x+Math.cos(a)*r,z:player.z+Math.sin(a)*r,hp:58,maxHp:58,phase:Math.random()*7,attack:1+Math.random()*2,hit:0,flash:0,target:false}}
for(let i=0;i<9;i++)enemies.push(spawnEnemy());
function burst(x,z,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*6.28,s=.8+Math.random()*2;particles.push({x,z,y:.3+Math.random()*.8,vx:Math.cos(a)*s,vz:Math.sin(a)*s,vy:1+Math.random()*2,life:.45+Math.random()*.55,color,size:2+Math.random()*3})}}
